Script:
Write-Output "Installing certificate..."

$certificateValue = [string]$Jaws.Parameters["STEP.CertificateValue"].Value
$certificatePassword = [string]$Jaws.Parameters["STEP.CertificatePassword"].Value
$storeLocationValue = [string]$Jaws.Parameters["STEP.CertificateStoreLocation"].Value
$storeName = [string]$Jaws.Parameters["STEP.CertificateStoreName"].Value
$friendlyName = [string]$Jaws.Parameters["STEP.CertificateFriendlyName"].Value

if ([string]::IsNullOrWhiteSpace($certificateValue)) {
  throw "Certificate value is required."
}

if ([string]::IsNullOrWhiteSpace($storeLocationValue)) {
  throw "Certificate store location is required."
}

if ([string]::IsNullOrWhiteSpace($storeName)) {
  throw "Certificate store name is required."
}

try {
  $storeLocation = [System.Enum]::Parse(
    [System.Security.Cryptography.X509Certificates.StoreLocation],
    $storeLocationValue,
    $true
  )
}
catch {
  throw "Invalid certificate store location '$storeLocationValue'. Use CurrentUser or LocalMachine."
}

$keyStorageFlags = [System.Security.Cryptography.X509Certificates.X509KeyStorageFlags]::PersistKeySet

if ($storeLocation -eq [System.Security.Cryptography.X509Certificates.StoreLocation]::LocalMachine) {
  $keyStorageFlags = $keyStorageFlags -bor [System.Security.Cryptography.X509Certificates.X509KeyStorageFlags]::MachineKeySet
}
else {
  $keyStorageFlags = $keyStorageFlags -bor [System.Security.Cryptography.X509Certificates.X509KeyStorageFlags]::UserKeySet
}

$certificate = $null
$store = $null

try {
  $certificateBytes = [System.Convert]::FromBase64String($certificateValue)
  $certificate = [System.Security.Cryptography.X509Certificates.X509Certificate2]::new(
    $certificateBytes,
    $certificatePassword,
    $keyStorageFlags
  )

  $store = [System.Security.Cryptography.X509Certificates.X509Store]::new(
    $storeName,
    $storeLocation
  )
  $store.Open([System.Security.Cryptography.X509Certificates.OpenFlags]::ReadWrite)

  $existing = $store.Certificates.Find(
    [System.Security.Cryptography.X509Certificates.X509FindType]::FindByThumbprint,
    $certificate.Thumbprint,
    $false
  )

  if ($existing.Count -gt 0) {
    Write-Output "Certificate already exists. Skipping."
  }
  else {
    if (-not [string]::IsNullOrWhiteSpace($friendlyName)) {
      $certificate.FriendlyName = $friendlyName
    }

    $store.Add($certificate)

    $verified = $store.Certificates.Find(
      [System.Security.Cryptography.X509Certificates.X509FindType]::FindByThumbprint,
      $certificate.Thumbprint,
      $false
    )

    if ($verified.Count -eq 0) {
      throw "Certificate could not be verified after import."
    }

    Write-Output "Certificate imported successfully."
  }
}
catch [System.FormatException] {
  throw "Certificate value is not valid Base-64 data."
}
finally {
  if ($null -ne $store) {
    $store.Dispose()
  }

  if ($null -ne $certificate) {
    $certificate.Dispose()
  }
}
